typedef struct {
    uint32_t 글자칸들[မှတ်တမ်းဟောင်းစာကြောင်းအရေအတွက်][최대열수]; uint8_t ပုံသဏ္ဌာန်များ[မှတ်တမ်းဟောင်းစာကြောင်းအရေအတွက်][최대열수];
    unsigned အနံတန်ဖိုး,အမြင့်တန်ဖိုး,ကော်လံအရေအတွက်,အတန်းလိုက်အရေအတွက်,크기바뀜;
    unsigned 살아있음,xတည်နေရာအမှတ်,yတည်နေရာအမှတ်,အတန်းလိုက်နေရာ,ကော်လံနေရာ,ထိပ်အချက်,လှိမ့်,전경색,နောက်ခံအရောင်,လွတ်,သတ်မှတ်အချက်တန်ဖိုး[4],သတ်မှတ်အချက်အညွှန်းကိန်း,သိမ်းပြီးအတန်းလိုက်,저장열;
    unsigned လက္ခဏာမပါရလဒ်,လက္ခဏာမပါရှည်တန်ဖိုး,작은값,대체화면,가리개보임;
} 터미널상태;
static 터미널상태 ဝင်းများစာရင်း[4];
