    if(끌기>=0&&!ဝင်းများစာရင်း[끌기].살아있음)끌기=-1;
    if(크기끌기>=0){
        ရွှေ့အရွယ်ပြောင်း(xတည်နေရာအမှတ်,yတည်နေရာအမှတ်);ဆားကစ်ပြားညွှန်တံ(xတည်နေရာအမှတ်,yတည်နေရာအမှတ်,잡은모서리==1||잡은모서리==4?2:3);return;
    }
    ဆားကစ်ပြားညွှန်တံ(xတည်နေရာအမှတ်,yတည်နေရာအမှတ်,1);
    if(끌기>=0){
        터미널상태 *ဝင်း=&ဝင်းများစာရင်း[끌기];
        int 옛가로=ဝင်း->xတည်နေရာအမှတ်,옛세로=ဝင်း->yတည်နေရာအမှတ်;
        ဝင်း->xတည်နေရာအမှတ်=사이값(xတည်နေရာအမှတ်-끌기가로,0,ဆားကစ်ပြားမျက်နှာပြင်အနံ()-ဝင်း->အနံတန်ဖိုး);
        ဝင်း->yတည်နေရာအမှတ်=사이값(yတည်နေရာအမှတ်-끌기세로,34,ဆားကစ်ပြားမျက်နှာပြင်အမြင့်()-ဝင်း->အမြင့်တန်ဖိုး);
        if(옛가로!=(int)ဝင်း->xတည်နေရာအမှတ်||옛세로!=(int)ဝင်း->yတည်နေရာအမှတ်)창자리그리기(옛가로,옛세로,ဝင်း->အနံတန်ဖိုး,ဝင်း->အမြင့်တန်ဖိုး,ဝင်း);
        return;
    }
    extern int 화면덮음(int,int,int);
    if(화면덮음(초점,xတည်နေရာအမှတ်,yတည်နေရာအမှတ်)){မျက်နှာပြင်ညွှန်တံ(초점,눌림,xတည်နေရာအမှတ်,yတည်နေရာအမှတ်);return;}
    int သတ်မှတ်နံပါတ်တန်ဖိုး=가리킨창(xတည်နေရာအမှတ်,yတည်နေရာအမှတ်),모서리=모서리찾기(သတ်မှတ်နံပါတ်တန်ဖိုး,xတည်နေရာအမှတ်,yတည်နေရာအမှတ်);
    if(모서리)ဆားကစ်ပြားညွှန်တံ(xတည်နေရာအမှတ်,yတည်နေရာအမှတ်,모서리==1||모서리==4?2:3);
