    if(လှုပ်ရှားမှု==13){터미널상태 *ဝင်း=&ဝင်းများစာရင်း[출력결과];return ဝင်း->살아있음?(ဝင်း->အတန်းလိုက်အရေအတွက်<<16)|ဝင်း->ကော်လံအရေအတွက်:(19<<16)|68;}
    if(လှုပ်ရှားမှု==14){unsigned တန်ဖိုး=ဝင်းများစာရင်း[출력결과].크기바뀜;ဝင်းများစာရင်း[출력결과].크기바뀜=0;return တန်ဖိုး;}
    if(လှုပ်ရှားမှု==12){unsigned တန်ဖိုး=ဖြစ်သောဆိုင်းငံ့;ဖြစ်သောဆိုင်းငံ့=0;return တန်ဖိုး;}
    if(လှုပ်ရှားမှု>=20&&လှုပ်ရှားမှု<24)return ဝင်းများစာရင်း[လှုပ်ရှားမှု-20].살아있음;
    if(လှုပ်ရှားမှု>=100&&လှုပ်ရှားမှု<104){출력결과=လှုပ်ရှားမှု-100;အဆုံးသုံးစက်အချက်=&ဝင်းများစာရင်း[출력결과];return 0;}
    if(လှုပ်ရှားမှု>=200&&လှုပ်ရှားမှု<204){앞으로올리기(လှုပ်ရှားမှု-200);return 0;}
    if(လှုပ်ရှားမှု==3){다시그리기();return 0;}အဆုံးသုံးစက်အချက်=&ဝင်းများစာရင်း[출력결과];if(!အဆုံးသုံးစက်အချက်->살아있음)return 0;
    if(လှုပ်ရှားမှု==4)အကြောင်းအရာရှင်း();if(လှုပ်ရှားမှု==5||လှုပ်ရှားမှု==6){unsigned ယခင်အချက်အလက်တစ်ခု=단추들;အဆုံးသုံးစက်ညွှန်တံ(လှုပ်ရှားမှု==5?8:16,0,0);단추들=ယခင်အချက်အလက်တစ်ခု;}return 1;
